import type { CircleProgressProps } from "./circle-progress.types";

import { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { CircleProgressClasses, StyledCircleProgress } from "./circle-progress.styles";

const CircleProgress = forwardRef(
  (
    { className, variant = "default", max = 100, value, ...props }: CircleProgressProps,
    ref: React.ForwardedRef<null>,
  ) => {
    const theme = useTheme();
    const isValueDefined = value != null;
    const rootClasses = clsx(CircleProgressClasses.root, className);
    const radius = 20;
    const circumference = 2 * Math.PI * radius;
    const dashOffset = isValueDefined ? circumference - (value / max) * circumference : undefined;

    return (
      <StyledCircleProgress
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
        aria-label={undefined}
      >
        <div
          aria-label={props["aria-label"]}
          aria-valuemax={max}
          aria-valuemin={0}
          className={clsx({
            [CircleProgressClasses.indeterminate]: !isValueDefined,
            [CircleProgressClasses.determinate]: isValueDefined,
          })}
          role="progressbar"
          {...(isValueDefined && { "aria-valuenow": value })}
        >
          <svg viewBox="22 22 44 44">
            <circle
              cx="44"
              cy="44"
              r={radius}
              strokeDasharray={circumference}
              strokeDashoffset={dashOffset}
            />
          </svg>
        </div>
      </StyledCircleProgress>
    );
  },
);

CircleProgress.displayName = "CircleProgress";

export default CircleProgress;
